/* saleson.shop.notice.NoticeMapper.getNoticeCount */
SELECT COUNT(*)
FROM OP_NOTICE N

	LEFT JOIN OP_NOTICE_SELLER S ON N.NOTICE_ID=S.NOTICE_ID



		AND SUB_CATEGORY = #{subCategory}


		AND CATEGORY_TEAM LIKE CONCAT('%', #{categoryTeam}, '%')



			AND SUBJECT LIKE CONCAT('%', #{query}, '%')


			AND CONTENT LIKE CONCAT('%', #{query}, '%')



		AND NOTICE_FLAG = #{noticeFlag}


		AND (VISIBLE_TYPE = #{visibleType} OR VISIBLE_TYPE = 1)


		AND (S.SELLER_ID=#{sellerId} OR N.SELLER_SELECT_FLAG = 'N')


		AND DATE_FORMAT(N.CREATED_DATE,'%Y%m%d') BETWEEN #{startCreateDate} AND #{endCreateDate}


		AND N.LOCGOV_CODE = #{locgovCode}





			AND BOARD_CODE = 'DONATION'


			AND (BOARD_CODE  <>   'DONATION' OR BOARD_CODE IS NULL)

/* saleson.shop.notice.NoticeMapper.getNoticeList */ SELECT A.notice_id, A.subject, A.url, A.category_team, crypto_dec('normal', A.user_name, '', 0) as user_name, A.password, A.email, A.content, A.hits, A.board_code, A.sub_category, A.created_date, A.target_option, A.rel_option, A.notice_flag, A.visible_type, A.seller_select_flag, A.new_flag, A.use_yn FROM ( SELECT N.notice_id, N.subject, N.url, N.category_team, N.user_name, N.password, N.email, N.content, N.hits, N.board_code, N.sub_category, N.created_date, N.target_option, N.rel_option, N.notice_flag, N.visible_type, N.seller_select_flag, CASE WHEN DATE_FORMAT(ADDDATE(STR_TO_DATE(N.created_date,'%Y%m%d%H%i%s'), INTERVAL 3 DAY),'%Y%m%d%H%i%s') >= THEN 'Y' ELSE 'N' END AS new_flag, N.use_yn, N.locgov_code FROM op_notice N ) A
LEFT JOIN op_notice_seller S ON A.notice_id=S.notice_id
AND (visible_type = #{visibleType} OR visible_type = 1)
AND sub_category = #{subCategory}
AND category_team LIKE CONCAT('%', #{categoryTeam}, '%')
AND notice_flag = #{noticeFlag}
AND subject LIKE CONCAT('%', #{query}, '%')
AND content LIKE CONCAT('%', #{query}, '%')
AND (S.seller_id=#{sellerId} OR A.seller_select_flag = 'N')
AND DATE_FORMAT(A.created_date,'%Y%m%d') BETWEEN #{startCreateDate} AND #{endCreateDate}
AND A.locgov_code = #{locgovCode}
AND board_code = 'DONATION'
AND (board_code <> 'DONATION' OR board_code IS NULL)
GROUP BY A.notice_id ORDER BY A.notice_flag DESC, A.notice_id DESC

mapper.insert:
/* saleson.shop.notice.NoticeMapper.insertNotice */
INSERT INTO OP_NOTICE (NOTICE_ID, SUBJECT, URL, CATEGORY_TEAM, USER_NAME, PASSWORD, EMAIL, CONTENT, HITS, BOARD_CODE, SUB_CATEGORY, CREATED_DATE, TARGET_OPTION, REL_OPTION, NOTICE_FLAG, VISIBLE_TYPE, SELLER_SELECT_FLAG, LOCGOV_CODE, USE_YN)
VALUES (#{noticeId}, #{subject}, #{url}, #{categoryTeam}, crypto_enc('normal', #{userName},''), #{password}, #{email}, #{content}, #{hits}, #{boardCode}, #{subCategory},  , #{targetOption}, #{relOption}, #{noticeFlag}, #{visibleType}, #{sellerSelectFlag}, #{locgovCode}, #{useYn})

/* saleson.shop.notice.NoticeMapper.insertNoticeSeller */
INSERT INTO OP_NOTICE_SELLER (NOTICE_SELLER_ID, NOTICE_ID, SELLER_ID, CREATED_DATE)
VALUES (#{noticeSellerId}, #{noticeId}, #{sellerId}, )

