mapper.select:
/* saleson.shop.notice.NoticeMapper.getFrontNoticeListByTeamCodes */ SELECT NOTICE_ID, SUBJECT, CASE WHEN URL IS NULL OR URL = '' THEN CONCAT('/board/view/',NOTICE_ID) ELSE TRIM(URL) END AS URL , CASE WHEN URL IS NULL OR URL = '' THEN 0 ELSE 1 END AS URL_TYPE , CATEGORY_TEAM, TARGET_OPTION, REL_OPTION, SUB_CATEGORY, CREATED_DATE FROM (
SELECT * FROM ( SELECT NOTICE_ID, SUBJECT, URL, #{teamCode} AS CATEGORY_TEAM, TARGET_OPTION, REL_OPTION, SUB_CATEGORY, CREATED_DATE FROM OP_NOTICE WHERE CATEGORY_TEAM LIKE CONCAT('%', #{teamCode}, '%') ORDER BY NOTICE_ID DESC LIMIT 5 ) T#{index}
) T

/* saleson.shop.notice.NoticeMapper.getNoticeSellerList */
SELECT NS.*, S.SELLER_NAME FROM OP_NOTICE_SELLER NS
INNER JOIN OP_SELLER S ON NS.SELLER_ID = S.SELLER_ID

WHERE NOTICE_ID = #{value}

/* saleson.shop.notice.NoticeMapper.getLocgovNoticeCount */
SELECT COUNT(*)
FROM OP_NOTICE N

	LEFT JOIN OP_NOTICE_SELLER S ON N.NOTICE_ID=S.NOTICE_ID



		AND SUB_CATEGORY = #{subCategory}


		AND CATEGORY_TEAM LIKE CONCAT('%', #{categoryTeam}, '%')



			AND SUBJECT LIKE CONCAT('%', #{query}, '%')


			AND CONTENT LIKE CONCAT('%', #{query}, '%')



		AND NOTICE_FLAG = #{noticeFlag}


		AND (VISIBLE_TYPE = #{visibleType} OR VISIBLE_TYPE = 1)


		AND (S.SELLER_ID=#{sellerId} OR N.SELLER_SELECT_FLAG = 'N')


		AND N.LOCGOV_CODE = #{locgovCode}


		AND DATE_FORMAT(N.CREATED_DATE,'%Y%m%d') BETWEEN #{startCreateDate} AND #{endCreateDate}

	AND N.LOCGOV_CODE != '00000'




			AND BOARD_CODE = 'DONATION'


			AND (BOARD_CODE  <>   'DONATION' OR BOARD_CODE IS NULL)

/* saleson.shop.notice.NoticeMapper.getLocgovNoticeList */ SELECT A.notice_id, A.subject, A.url, A.category_team, crypto_dec('normal', A.user_name, '', 0) as user_name, A.password, A.email, A.content, A.hits, A.board_code, A.sub_category, A.created_date, A.target_option, A.rel_option, A.notice_flag, A.visible_type, A.seller_select_flag, A.locgov_nm, A.use_yn FROM ( SELECT N.notice_id, N.subject, N.url, N.category_team, N.user_name, N.password, N.email, N.content, N.hits, N.board_code, N.sub_category, N.created_date, N.target_option, N.rel_option, N.notice_flag, N.visible_type, N.seller_select_flag, CASE WHEN DATE_FORMAT(ADDDATE(STR_TO_DATE(N.created_date,'%Y%m%d%H%i%s'), INTERVAL 3 DAY),'%Y%m%d%H%i%s') >= THEN 'Y' ELSE 'N' END AS new_flag ,(SELECT CONCAT(upper_locgov_nm, ' ',locgov_nm) FROM g_locgov where locgov_code=N.locgov_code ) AS locgov_nm , use_yn , N.locgov_code FROM op_notice N
LEFT JOIN op_notice_seller S ON N.notice_id=S.notice_id AND (S.SELLER_ID=#{sellerId} OR N.SELLER_SELECT_FLAG = 'N')
) A
AND (VISIBLE_TYPE = #{visibleType} OR VISIBLE_TYPE = 1)
AND SUB_CATEGORY = #{subCategory}
AND CATEGORY_TEAM LIKE CONCAT('%', #{categoryTeam}, '%')
AND NOTICE_FLAG = #{noticeFlag}
AND SUBJECT LIKE CONCAT('%', #{query}, '%')
AND CONTENT LIKE CONCAT('%', #{query}, '%')
AND A.LOCGOV_CODE = #{locgovCode}
AND DATE_FORMAT(A.CREATED_DATE,'%Y%m%d') BETWEEN #{startCreateDate} AND #{endCreateDate}
AND A.LOCGOV_CODE != '00000'
AND BOARD_CODE = 'DONATION'
AND (BOARD_CODE <> 'DONATION' OR BOARD_CODE IS NULL)
GROUP BY A.NOTICE_ID ORDER BY A.NOTICE_FLAG DESC, A.NOTICE_ID DESC

